import{z as s,x as o,o as e,c as D,q as t,j as i,D as a,d as A,s as n,S as r,b as l}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"许可与合规","description":"","frontmatter":{"title":"许可与合规","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/synthetic-license-compliance.md","filePath":"llm/synthetic-license-compliance.md","lastUpdated":1791063341000}'),d={name:"llm/synthetic-license-compliance.md"};function c(p,E,m,h,C,f){const B=o("Mermaid");return e(),D("div",null,[E[2]||(E[2]=t('<h1 id="许可与合规" tabindex="-1">许可与合规 <a class="header-anchor" href="#许可与合规" aria-label="Permalink to &quot;许可与合规&quot;">​</a></h1><div class="epigraph"><p>「数据是合成的，所以没有版权问题」是这门工程里最贵的一句错觉：合成只是换了一条传播链，没有换掉任何一环义务。</p><footer>—— 据 BigCode The Stack v2 的许可门；本站记忆化与版权课整理</footer></div><p><a href="/llm/synthetic-scaling-laws">上一课</a>算清了配方的收益账；本课算另一本账：这条生产线能不能合法地存在、发布、商用。原料许可门在<a href="/llm/code-license-gate">代码许可与质量门</a>与 <a href="/llm/the-stack-v2">The Stack v2</a>已立，版权与记忆化的关系在<a href="/llm/memorization-copyright">记忆化与版权</a>讲清：版权关心复制，事实正确不自动豁免。本课把四条链的合规义务串成一条流水线，并指出合成在哪几环重新打开了本来已经关上的门。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>合成数据有四条链，各自带义务。原料链：种子的许可（仓库、网页、教材）决定生成物的第一重血统——copyleft 与「仅限研究」的原料混进种子池，整批数据继承可疑地位。教师链：两层约束常被漏看——API 服务条款可能限制「用输出训练竞争模型」；开源权重许可的附加条款（命名、用途限制、分发条件）约束「用教师造数据训学生」这件事本身。输出链：教师可能近乎逐字地吐出训练语料，合成批次因此夹带受版权保护的长片段——「合成」的外衣不改变复制的实质。人格与隐私链：种子与真实锚点里的个人信息会在改写中被保留、组合甚至放大，合成不自动匿名。<span class="marginnote">术语翻译：copyleft 是一类「传染性」开源许可（如 GPL）——要求衍生作品沿用同等许可继续开放。它混进种子池后，下游数据与模型的分发条款都可能被连带追问。很多数据集整体排除它，不是因为「坏」，而是因为它带来连带的开放义务。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流水线五道门，随管线走。许可门：种子入库前过 SPDX 级检测，粒度从严，低置信度按从严处理并记录；许可口径写成策略而不是逐案判断。条款门：教师的选择本身是合规决策——用哪家教师的输出训模型，先读它的条款与权重许可，把约束写进数据台账。近复制门：对生成批次做与源语料的长片段重叠检测，命中即丢弃或截断——这是去重关卡在合规侧的第二身份，用的是同一套 <a href="/llm/minhash-dedup">MinHash</a> 基建，但阈值与目的不同。隐私门：<a href="/llm/pii-redact">PII 去除</a>的跨度改写跑在合成之后而非之前——改写可能把遮掉的实体重新带回来。台账门：每批数据记录来源、教师版本、过滤与检测记录，<a href="/llm/instruction-data-lineage">数据谱系</a>的谱系表升级为合规台账；发布时模型卡声明合成占比与教师血统。</p>',7)),(e(),i(r,null,{default:a(()=>[n(B,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEED%5B%22%E7%A7%8D%E5%AD%90%E5%85%A5%E5%BA%93%22%5D%20--%3E%20LIC%7B%22SPDX%20%E8%AE%B8%E5%8F%AF%E6%A3%80%E6%B5%8B%22%7D%0A%20%20LIC%20--%3E%7C%E4%B8%8D%E5%90%88%E8%A7%84%7C%20OUT%5B%22%E6%8B%92%E7%BB%9D%E5%85%A5%E5%BA%93%22%5D%0A%20%20LIC%20--%3E%7C%E5%90%88%E8%A7%84%7C%20TEA%7B%22%E6%95%99%E5%B8%88%E6%9D%A1%E6%AC%BE%E5%85%81%E8%AE%B8%EF%BC%9F%22%7D%0A%20%20TEA%20--%3E%7C%E5%90%A6%7C%20OUT%0A%20%20TEA%20--%3E%7C%E6%98%AF%7C%20GEN%5B%22%E7%94%9F%E6%88%90%E6%89%B9%E6%AC%A1%22%5D%0A%20%20GEN%20--%3E%20NEAR%7B%22%E8%BF%91%E5%A4%8D%E5%88%B6%E6%A3%80%E6%B5%8B%EF%BC%9A%E5%AF%B9%E6%BA%90%E8%AF%AD%E6%96%99%22%7D%0A%20%20NEAR%20--%3E%7C%E5%91%BD%E4%B8%AD%E9%95%BF%E7%89%87%E6%AE%B5%7C%20CUT%5B%22%E4%B8%A2%E5%BC%83%E6%88%96%E6%88%AA%E6%96%AD%22%5D%0A%20%20NEAR%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20PII%5B%22PII%20%E8%B7%A8%E5%BA%A6%E6%94%B9%E5%86%99%22%5D%0A%20%20PII%20--%3E%20LEDGER%5B%22%E5%90%88%E8%A7%84%E5%8F%B0%E8%B4%A6%E5%85%A5%E5%BA%93%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l("h2",{id:"机制",tabindex:"-1"},[A("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=l("p",null,"为什么「合成即安全」是错觉：版权分析的对象是复制行为与实质性相似，不是数据的生产方式。教师是训练语料的高度有损压缩，压缩到局部仍可能近乎无损——高频片段、著名文本、模板化代码正是记忆化最强的地方，也恰好是合成生成最容易命中的地方。近复制检测因此不是可选审计而是结构性部件：它与质量去重共享工具但目标相反——质量去重要删「池内重复」，合规检测要删「与外部源语料的重叠」。教师链的机制地位更高：它决定整条线的合法性上限，条款不允许时，后面的门修得再好也无效，所以条款门排在最前。台账的机制价值在于把合规从一次性审查变成可追溯的状态：许可证检查可以在源库变更后重跑，作者退出请求可以按台账定位批次重处理。",-1)),(e(),i(r,null,{default:a(()=>[n(B,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E6%95%99%E5%B8%88%20%3D%20%E8%AE%AD%E7%BB%83%E8%AF%AD%E6%96%99%E7%9A%84%E9%AB%98%E5%BA%A6%E6%9C%89%E6%8D%9F%E5%8E%8B%E7%BC%A9%22%5D%20--%3E%20H%5B%22%E5%B1%80%E9%83%A8%E4%BB%8D%E8%BF%91%E4%B9%8E%E6%97%A0%E6%8D%9F%3A%20%E9%AB%98%E9%A2%91%E7%89%87%E6%AE%B5%2F%E8%91%97%E5%90%8D%E6%96%87%E6%9C%AC%2F%E6%A8%A1%E6%9D%BF%E4%BB%A3%E7%A0%81%22%5D%0A%20%20H%20--%3E%20L%5B%22%E5%90%88%E6%88%90%E6%89%B9%E6%AC%A1%E5%A4%B9%E5%B8%A6%E9%95%BF%E7%89%87%E6%AE%B5%2C%20%E5%A4%8D%E5%88%B6%E7%9A%84%E5%AE%9E%E8%B4%A8%E6%B2%A1%E5%8F%98%22%5D%0A%20%20L%20--%3E%20N%5B%22%E8%BF%91%E5%A4%8D%E5%88%B6%E9%97%A8%3A%20%E4%B8%8E%E5%A4%96%E9%83%A8%E6%BA%90%E8%AF%AD%E6%96%99%E5%81%9A%E9%95%BF%E7%89%87%E6%AE%B5%E9%87%8D%E5%8F%A0%E6%A3%80%E6%B5%8B%22%5D%0A%20%20D%5B%22%E8%B4%A8%E9%87%8F%E5%8E%BB%E9%87%8D%3A%20%E5%8F%AA%E5%88%A0%E6%B1%A0%E5%86%85%E4%BA%92%E7%9B%B8%E9%87%8D%E5%A4%8D%22%5D%20-.%20%E5%90%8C%E4%B8%80%E5%B7%A5%E5%85%B7%2C%20%E4%B8%8D%E5%90%8C%E7%9B%AE%E6%A0%87%20.-%3E%20N%0A%20%20N%20--%3E%20OK%5B%22%E5%91%BD%E4%B8%AD%E5%8D%B3%E6%88%AA%E6%96%AD%E6%88%96%E4%B8%A2%E5%BC%83%2C%20%E5%8F%91%E5%B8%83%E6%89%8D%E6%9C%89%E5%90%88%E8%A7%84%E5%9F%BA%E7%A1%80%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">直觉类比：教师像把一座图书馆压成一本摘要笔记——整体上丢了很多细节，但名句、常用代码模板这类高频内容会被近乎逐字记住。「我们没存原书，只用了笔记」在版权上站不住：笔记里可能整段就是原文。</span></p><p><span class="marginnote">The Stack v2 的口径：许可在文件级检测，纳入宽松与无许可、排除 copyleft 与商业许可，配合退出机制与稳定标识（SWHID）做问责——「能追溯」是合规的第一属性，比任何单一检测规则都基础。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课是工程口径不是法律意见：管辖区差异、合理使用的边界、条款的可执行性都要专业判断；工程的角色是把事实——来源、检测记录、版本——准备到可供专业判断的状态。近复制检测对改写级复制的召回有限，风格模仿的争议（声音、笔名、画风）大多不在检测器射程内，靠用途政策兜底。退出机制的时效滞后于采集，台账只能保证「可响应」，不保证「从未包含」。跨辖区商用还有输出合规（模型行为）与数据合规（训练过程）两层，本课只覆盖后者。<span class="marginnote">为什么重要：某作者撤回对一段种子的授权时，有台账就能按谱系定位「哪些批次用过它」，重跑过滤甚至重训；没有台账，只能整批作废。合规台账买的不是「从未包含」，而是「出事时能响应」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四条链：原料许可、教师条款、输出近复制、隐私人格；合成不豁免任何一环。</li><li>条款门排最前：教师选择决定整条线的合法性上限。</li><li>近复制检测与去重同工具不同目的：删的是与外部源语料的重叠。</li><li>PII 改写跑在合成之后；台账让合规成为可重跑的状态。</li><li>发布声明合成占比与教师血统；工程备事实，法律判断另请专业。</li><li>出处：Kocetkov 等 The Stack v2 2024；本站记忆化与版权、PII 去除两课。</li></ul>',6))])}const _=s(d,[["render",c]]);export{T as __pageData,_ as default};
